function getJeeMainExactQuestionKey(question) {
    return String(
        question && (question.source || question.qHtml || question.q || '')
    ).replace(/\s+/g, ' ').trim().toLowerCase().slice(0, 700);
}

function mergeJeeMainExactQuestions(existingQuestions, importedQuestions) {
    const seen = new Set();
    const merged = [];

    [...(Array.isArray(existingQuestions) ? existingQuestions : []), ...(Array.isArray(importedQuestions) ? importedQuestions : [])].forEach((question) => {
        if (!question || !question.exactPaperText) return;
        const key = getJeeMainExactQuestionKey(question);
        if (!key || seen.has(key)) return;
        seen.add(key);
        merged.push(question);
    });

    return merged.slice(0, 50);
}

Object.entries(MHT_CET_JEE_MAIN_PYQ_BANK).forEach(([chapterName, importedQuestions]) => {
    if (!Array.isArray(importedQuestions) || importedQuestions.length === 0) return;

    const existingQuestions = Array.isArray(chapters[chapterName]) ? chapters[chapterName] : [];
    const mergedQuestions = mergeJeeMainExactQuestions(existingQuestions, importedQuestions);
    if (!mergedQuestions.length) return;

    chapters[chapterName] = mergedQuestions;
    CHAPTER_PART_SIZE_OVERRIDES[chapterName] = 10;
});

